// ── Validate, screen, and record the signup ────────────────────────────────
// Storage lives in n8n's workflow static data so this runs with zero external
// setup. It is fine for a list that is starting from nothing, but it is NOT a
// durable system of record — see _n8n/README.md for the one function to swap
// when you move to a real datastore.
const store = $getWorkflowStaticData('global');
store.subscribers = store.subscribers || {};

const input   = $input.first().json;
const body    = input.body || input;
const headers = input.headers || {};

function newToken() {
  try { return crypto.randomUUID().replace(/-/g, ''); }
  catch (e) {
    return (Date.now().toString(36) +
            Math.random().toString(36).slice(2) +
            Math.random().toString(36).slice(2)).slice(0, 32);
  }
}

const email    = String(body.email || '').trim().toLowerCase();
const consent  = body.consent === true;
const language = body.language === 'pt' ? 'pt' : 'en';

// The website screens before it gets here, but never trust the client: this
// endpoint is public and anyone can POST to it directly.
const emailOk = /^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/.test(email) && email.length <= 254;

if (!emailOk || !consent) {
  return [{ json: {
    ok: false, httpStatus: 400, sendEmail: false,
    error: !consent ? 'consent_required' : 'invalid_email'
  }}];
}

const now      = new Date().toISOString();
const existing = store.subscribers[email];

// Already subscribed: do nothing, and reply exactly as we do to everyone else.
// Never disclose whether an address is on the list.
if (existing && existing.status === 'confirmed') {
  return [{ json: { ok: true, httpStatus: 200, sendEmail: false, email } }];
}

const token = newToken();

store.subscribers[email] = {
  email,
  status: 'pending',
  token,
  // Consent evidence. consent_text is the exact wording rendered next to the
  // checkbox at the moment they ticked it — that is what makes this a record
  // rather than a flag.
  consent: true,
  consent_text: String(body.consent_text || '').slice(0, 500),
  consent_at:   body.consent_at || now,
  consent_ip:   headers['x-forwarded-for'] || headers['x-real-ip'] || null,
  language,
  source:     String(body.source || '').slice(0, 100),
  entry_page: String(body.entry_page || '').slice(0, 200),
  requested_at:    now,
  confirmed_at:    (existing && existing.confirmed_at) || null,
  unsubscribed_at: null
};

const confirmUrl = 'https://lumenandpixel.app.n8n.cloud/webhook/newsletter-confirm'
  + '?email=' + encodeURIComponent(email)
  + '&token=' + encodeURIComponent(token);

const copy = language === 'pt'
  ? {
      subject: 'Confirme a sua subscricao — Lumen and Pixel',
      lead:    'Falta apenas um passo.',
      body:    'Clique no botao abaixo para confirmar que pretende receber emails da Lumen and Pixel.',
      cta:     'Confirmar subscricao',
      ignore:  'Se nao foi voce a pedir isto, ignore este email — nada acontecera.'
    }
  : {
      subject: 'Confirm your subscription — Lumen and Pixel',
      lead:    'One step left.',
      body:    'Click the button below to confirm you want to receive emails from Lumen and Pixel.',
      cta:     'Confirm subscription',
      ignore:  'If you did not request this, just ignore this email — nothing will happen.'
    };

const html = `<!DOCTYPE html><html><body style="margin:0;background:#021829;font-family:Helvetica,Arial,sans-serif;color:#f0f1f3;">
  <div style="max-width:520px;margin:0 auto;padding:40px 24px;">
    <p style="font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:#33fb31;margin:0 0 18px;">Lumen and Pixel</p>
    <h1 style="font-size:24px;line-height:1.25;margin:0 0 14px;">${copy.lead}</h1>
    <p style="font-size:15px;line-height:1.7;color:#b8bec8;margin:0 0 28px;">${copy.body}</p>
    <a href="${confirmUrl}" style="display:inline-block;background:#33fb31;color:#021829;font-weight:700;font-size:14px;padding:14px 28px;border-radius:3px;text-decoration:none;">${copy.cta}</a>
    <p style="font-size:12px;line-height:1.6;color:#6b7485;margin:32px 0 0;">${copy.ignore}</p>
  </div>
</body></html>`;

return [{ json: {
  ok: true, httpStatus: 200, sendEmail: true,
  email, token, language,
  subject: copy.subject,
  html
}}];

// ── Confirm a pending subscription ─────────────────────────────────────────
// This is the moment consent becomes verified. Only a matching, unused token
// flips a record to confirmed.
const store = $getWorkflowStaticData('global');
store.subscribers = store.subscribers || {};

const q     = $input.first().json.query || {};
const email = String(q.email || '').trim().toLowerCase();
const token = String(q.token || '');

const rec = store.subscribers[email];
const ok  = Boolean(rec && rec.status === 'pending' && rec.token && token && rec.token === token);

if (ok) {
  rec.status       = 'confirmed';
  rec.confirmed_at = new Date().toISOString();
  rec.token        = null;          // single use
}

return [{ json: { ok, email, language: (rec && rec.language === 'pt') ? 'pt' : 'en' } }];

// ── Unsubscribe ────────────────────────────────────────────────────────────
// Every email you send must link here. Honouring it is a legal requirement,
// not a courtesy — and unhonoured unsubscribes are what destroy sender
// reputation.
const store = $getWorkflowStaticData('global');
store.subscribers = store.subscribers || {};

const q     = $input.first().json.query || {};
const email = String(q.email || '').trim().toLowerCase();

const rec = store.subscribers[email];
const pt  = rec && rec.language === 'pt';

if (rec) {
  rec.status          = 'unsubscribed';
  rec.unsubscribed_at = new Date().toISOString();
  rec.token           = null;
}

// Answer the same way whether or not the address was on the list.
const message = pt
  ? 'Subscricao cancelada. Nao voltara a receber os nossos emails.'
  : 'You have been unsubscribed. You will not receive further emails from us.';

return [{ json: { message } }];
